/**
 * READING & STUDY 05 — SPACED REPETITION FLASHCARDS
 * Original, asset-free 2D Canvas artwork. One continuous 25-second scene.
 * Call draw(ctx, timeInSeconds, width, height); frames may be requested in any order.
 * External export target: 3840 x 2160, 60 fps, 100 Mbps CBR.
 * The encoder must enforce 100,000,000 bits/s; Canvas itself has no bitrate.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const cycle = (currentScene + sceneProgress) * 3;
  const cycleIndex = Math.floor(cycle) % 3;
  const p = cycle - Math.floor(cycle);
  const clamp = (v) => Math.max(0, Math.min(1, v));
  const smooth = (v) => { const q = clamp(v); return q * q * q * (q * (q * 6 - 15) + 10); };
  const ramp = (a, b, v) => smooth((v - a) / (b - a));
  const mix = (a, b, q) => a + (b - a) * q;
  const ink = '#29394c';
  const fontStack = 'Arial, Helvetica, "DejaVu Sans", sans-serif';
  const palettes = [
    { accent: '#b8a7d3', pale: '#ebe5f1', deep: '#827496' },
    { accent: '#e3b595', pale: '#f1e8dc', deep: '#a97f68' },
    { accent: '#91bdb2', pale: '#e0ece3', deep: '#5d9287' }
  ];
  const answerTitles = ['REPEAT & REFLECT', 'CONNECT THE IDEAS', 'REVIEW REGULARLY'];
  const withdraw = ramp(0.60, 0.80, p);
  const returning = ramp(0.80, 1, p);
  const promote = ramp(0.70, 0.90, p);
  const advance = ramp(0.72, 1, p);

  function rr(x, y, w, h, r) {
    const k = Math.min(r, w / 2, h / 2);
    ctx.beginPath(); ctx.moveTo(x + k, y); ctx.lineTo(x + w - k, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + k); ctx.lineTo(x + w, y + h - k);
    ctx.quadraticCurveTo(x + w, y + h, x + w - k, y + h); ctx.lineTo(x + k, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - k); ctx.lineTo(x, y + k);
    ctx.quadraticCurveTo(x, y, x + k, y); ctx.closePath();
  }
  function box(x, y, w, h, r, fill, stroke, lw) {
    if (w <= 0 || h <= 0) return;
    rr(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, color, lw) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
  }
  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }
  function text(value, x, y, size, color, align, maxWidth, alpha) {
    ctx.font = '700 ' + size + 'px ' + fontStack;
    const measured = ctx.measureText(value).width;
    if (measured > maxWidth) ctx.font = '700 ' + (size * maxWidth / measured) + 'px ' + fontStack;
    ctx.textAlign = align || 'center'; ctx.textBaseline = 'alphabetic';
    ctx.save(); ctx.globalAlpha *= alpha === undefined ? 1 : alpha;
    ctx.fillStyle = color; ctx.fillText(value, x, y); ctx.restore();
  }
  function bezier(a, b, c, d, q) {
    const s = 1 - q;
    return { x: s * s * s * a.x + 3 * s * s * q * b.x + 3 * s * q * q * c.x + q * q * q * d.x,
      y: s * s * s * a.y + 3 * s * s * q * b.y + 3 * s * q * q * c.y + q * q * q * d.y };
  }
  function check(cx, cy, amount, color) {
    const a = { x: cx - 19, y: cy }, b = { x: cx - 4, y: cy + 14 }, c = { x: cx + 23, y: cy - 18 };
    const first = Math.hypot(b.x - a.x, b.y - a.y), second = Math.hypot(c.x - b.x, c.y - b.y);
    const distance = clamp(amount) * (first + second);
    if (distance <= 0) return;
    ctx.beginPath(); ctx.moveTo(a.x, a.y);
    if (distance < first) ctx.lineTo(mix(a.x, b.x, distance / first), mix(a.y, b.y, distance / first));
    else {
      ctx.lineTo(b.x, b.y); const q = (distance - first) / second;
      ctx.lineTo(mix(b.x, c.x, q), mix(b.y, c.y, q));
    }
    ctx.strokeStyle = color; ctx.lineWidth = 6; ctx.stroke();
  }
  function drawCard(id, pose, active) {
    const color = palettes[id];
    ctx.save(); ctx.translate(pose.x, pose.y); ctx.rotate(pose.angle);
    // Flat paper and category tab; all parts share one rigid local coordinate frame.
    box(-225, -244, 110, 38, 10, color.accent, ink, 3.5);
    text('SET ' + String.fromCharCode(65 + id), -170, -227, 11, ink, 'center', 91);
    const paper = ctx.createLinearGradient(-280, -220, 280, 220);
    paper.addColorStop(0, '#f7f2e7'); paper.addColorStop(1, '#e9e9dc');
    box(-280, -220, 560, 440, 26, paper, ink, 5);
    box(-268, -208, 536, 416, 18, null, '#c9cfc2', 1.5);
    text('ACTIVE RECALL', -237, -171, 16, '#637277', 'left', 319);
    box(174, -195, 65, 31, 9, color.pale, color.accent, 1.8);
    text('0' + (id + 1), 206.5, -173, 15, color.deep, 'center', 47);
    line(-237, -148, 237, -148, '#cad1c3', 2);
    const headerPhase = (sceneProgress * 9 + 0.18) % 1;
    ctx.save(); ctx.globalAlpha *= 0.75 * Math.pow(Math.sin(Math.PI * headerPhase), 2);
    circle(-231 + 462 * headerPhase, -148, 3, color.deep); ctx.restore();

    const questionAlpha = active ? 1 - ramp(0.16, 0.21, p) + ramp(0.84, 0.94, p) : 1;
    const answerVisibility = active ? 1 - ramp(0.63, 0.76, p) : 0;
    const reveal = active ? ramp(0.22, 0.38, p) : 0;
    const answerType = active ? ramp(0.38, 0.44, p) : 0;
    ctx.save(); ctx.globalAlpha *= questionAlpha;
    circle(0, -55, 44, color.pale, color.accent, 3);
    text('?', 0, -32, 64, color.deep, 'center', 70);
    text('What do you', 0, 38, 29, ink, 'center', 441);
    text('remember?', 0, 77, 29, ink, 'center', 441);
    const scan = active && p < 0.16 ? clamp(p / 0.16) : 0;
    const scanAlpha = Math.pow(Math.sin(Math.PI * scan), 2);
    ctx.save(); ctx.globalAlpha *= scanAlpha;
    line(-98, 103, -98 + 196 * smooth(scan), 103, color.deep, 3);
    ctx.restore(); ctx.restore();

    // The answer is revealed by a planar mask. Typography is staged after the wipe.
    // No mirrored text, 3D flip, nonuniform scaling or partial mixed words.
    if (reveal > 0 && answerVisibility > 0) {
      ctx.save(); ctx.globalAlpha *= answerVisibility;
      rr(-244, -124, 488, 250, 17); ctx.clip();
      ctx.beginPath(); ctx.rect(-244, -124, 488 * reveal, 250); ctx.clip();
      box(-244, -124, 488, 250, 17, '#e0ebe0');
      ctx.save(); ctx.globalAlpha *= answerType;
      circle(0, -55, 44, '#669c8a', '#487d70', 3);
      check(0, -55, ramp(0.38, 0.46, p), '#f7f2dc');
      ctx.restore();
      text(answerTitles[id], 0, 40, 25, '#365e54', 'center', 438, answerType);
      ctx.save(); ctx.globalAlpha *= answerType;
      box(-170, 70, 340, 6, 3, '#89a296');
      box(-133, 92, 266, 6, 3, '#9bb0a2');
      ctx.restore(); ctx.restore();
    }
    const mastery = active ? ramp(0.44, 0.59, p) : 0;
    text('RECALL PROGRESS', 0, 155, 12, '#7c8a7e', 'center', 350);
    for (let i = 0; i < 5; i++) {
      const x = -218 + i * 90;
      box(x, 177, 76, 8, 4, '#cfd7c9');
      const alpha = smooth(mastery * 5 - i) * answerVisibility;
      if (alpha > 0) { ctx.save(); ctx.globalAlpha *= alpha; box(x, 177, 76, 8, 4, '#73a38d'); ctx.restore(); }
    }
    ctx.restore();
  }

  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over'; ctx.filter = 'none';
  ctx.shadowBlur = 0; ctx.shadowColor = 'transparent'; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
  ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.setLineDash([]);
  const background = ctx.createLinearGradient(0, 0, width, height);
  background.addColorStop(0, '#191b31'); background.addColorStop(0.56, '#25283d');
  background.addColorStop(1, '#31273f');
  ctx.fillStyle = background; ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2 + 20 * scale, height / 2 - 18 * scale); ctx.scale(scale, scale);

  const middle = { x: mix(45, 0, promote), y: mix(32, 0, promote), angle: mix(0.04, 0, promote) };
  const back = { x: mix(70, 45, advance), y: mix(52, 32, advance), angle: mix(0.07, 0.04, advance) };
  let front;
  if (p < 0.80) {
    front = { x: -590 * withdraw, y: -40 * withdraw - 17 * Math.sin(Math.PI * withdraw), angle: -0.05 * withdraw };
  } else {
    const pos = bezier({ x: -590, y: -40 }, { x: -620, y: 205 }, { x: -135, y: 320 }, { x: 70, y: 52 }, returning);
    front = { x: pos.x, y: pos.y, angle: mix(-0.05, 0.07, returning) };
  }
  // Layer order changes only in the side corridor, once card bounds are separate.
  // The returning card then passes behind the stack as an intentional occlusion.
  if (p >= 0.80) drawCard(cycleIndex, front, true);
  drawCard((cycleIndex + 2) % 3, back, false);
  drawCard((cycleIndex + 1) % 3, middle, false);
  if (p < 0.80) drawCard(cycleIndex, front, true);
  ctx.restore();
}

draw.duration = 25;
draw.fps = 60;
draw.sceneCount = 1;
draw.exportSettings = { width: 3840, height: 2160, targetVideoBitrate: 100000000 };

/**
 * READING & STUDY 06 — RESEARCH READING LENS
 * Original, asset-free 2D Canvas artwork. One continuous 25-second scene.
 * Call draw(ctx, timeInSeconds, width, height); frames may be requested in any order.
 * External export target: 3840 x 2160, 60 fps, 100 Mbps CBR.
 * The encoder must enforce 100,000,000 bits/s; Canvas itself has no bitrate.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const sceneT = (currentScene + sceneProgress) * sceneDuration;
  const TAU = Math.PI * 2;
  const clamp = (v) => Math.max(0, Math.min(1, v));
  const smooth = (v) => { const q = clamp(v); return q * q * q * (q * (q * 6 - 15) + 10); };
  const ramp = (a, b) => smooth((sceneT - a) / (b - a));
  const window = (a, b, c, d) => ramp(a, b) * (1 - ramp(c, d));
  const mix = (a, b, q) => a + (b - a) * q;
  const ink = '#203e49';
  const fontStack = 'Arial, Helvetica, "DejaVu Sans", sans-serif';
  const selection = window(8.45, 9.4, 17.25, 18.45);
  const connection = window(9.05, 10.5, 17.6, 18.6);
  const sourceOpen = window(9.5, 10.6, 17.1, 18.4);
  const lensRadius = 132;
  const magnification = 1.38;

  function bezier(a, b, c, d, q) {
    const s = 1 - q;
    return { x: s * s * s * a.x + 3 * s * s * q * b.x + 3 * s * q * q * c.x + q * q * q * d.x,
      y: s * s * s * a.y + 3 * s * s * q * b.y + 3 * s * q * q * c.y + q * q * q * d.y };
  }
  const A = { x: -218, y: -47 }, B = { x: -78, y: 3 };
  const C = { x: -120, y: 89 }, D = { x: -246, y: 152 };
  let lens;
  if (sceneT < 5.5) lens = bezier(A, { x: -170, y: -110 }, { x: -93, y: -90 }, B, ramp(0, 5.5));
  else if (sceneT < 8.4) lens = bezier(B, { x: -62, y: 41 }, { x: -76, y: 90 }, C, ramp(5.5, 8.4));
  else if (sceneT < 17.2) lens = C;
  else if (sceneT < 22) lens = bezier(C, { x: -155, y: 133 }, { x: -217, y: 168 }, D, ramp(17.2, 22));
  else lens = bezier(D, { x: -310, y: 102 }, { x: -310, y: -26 }, A, ramp(22, 25));

  function rr(x, y, w, h, r) {
    const k = Math.min(r, w / 2, h / 2);
    ctx.beginPath(); ctx.moveTo(x + k, y); ctx.lineTo(x + w - k, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + k); ctx.lineTo(x + w, y + h - k);
    ctx.quadraticCurveTo(x + w, y + h, x + w - k, y + h); ctx.lineTo(x + k, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - k); ctx.lineTo(x, y + k);
    ctx.quadraticCurveTo(x, y, x + k, y); ctx.closePath();
  }
  function box(x, y, w, h, r, fill, stroke, lw) {
    if (w <= 0 || h <= 0) return;
    rr(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, color, lw) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
  }
  function circle(x, y, r, fill, stroke, lw) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }
  function text(value, x, y, size, color, align, maxWidth, alpha) {
    ctx.font = '700 ' + size + 'px ' + fontStack;
    const measured = ctx.measureText(value).width;
    if (measured > maxWidth) ctx.font = '700 ' + (size * maxWidth / measured) + 'px ' + fontStack;
    ctx.textAlign = align || 'left'; ctx.textBaseline = 'alphabetic';
    ctx.save(); ctx.globalAlpha *= alpha === undefined ? 1 : alpha;
    ctx.fillStyle = color; ctx.fillText(value, x, y); ctx.restore();
  }
  function dashRow(x, y, width, color, h) {
    const gap = 9, available = width - gap * 2;
    const parts = [0.39, 0.32, 0.29];
    let left = x;
    for (let i = 0; i < parts.length; i++) {
      const w = available * parts[i]; box(left, y, w, h, h / 2, color); left += w + gap;
    }
  }
  function paper() {
    const fill = ctx.createLinearGradient(-455, -365, 195, 365);
    fill.addColorStop(0, '#f7f3e7'); fill.addColorStop(1, '#e9eddf');
    box(-455, -365, 650, 730, 26, fill);
  }
  function content() {
    text('REFERENCE READING', -406, -316, 15, '#678579', 'left', 482);
    text('READ. RESEARCH.', -406, -269, 31, ink, 'left', 546);
    text('UNDERSTAND.', -406, -227, 31, ink, 'left', 546);
    line(-406, -198, 145, -198, '#cbd7c7', 2);
    const headerPhase = (sceneProgress * 5 + 0.18) % 1;
    ctx.save(); ctx.globalAlpha *= Math.pow(Math.sin(Math.PI * headerPhase), 2) * 0.8;
    circle(-401 + 541 * headerPhase, -198, 3.1, '#6d9c8a'); ctx.restore();
    const rows = [514, 482, 527, 438];
    for (let i = 0; i < rows.length; i++) dashRow(-406, -139 + i * 33, rows[i], '#92a196', 7);

    box(-410, 36, 544, 115, 14, '#e1e9dc');
    if (selection > 0) {
      ctx.save(); ctx.globalAlpha *= selection;
      box(-410, 36, 544, 115, 14, '#f0d7a6'); ctx.restore();
    }
    box(-410, 36, 6, 115, 3, '#7ca591');
    // Quotation marks are geometric paths, avoiding any glyph dependency.
    for (let j = 0; j < 2; j++) {
      box(-385 + j * 16, 58, 9, 10, 2, '#789683');
      line(-381 + j * 16, 68, -385 + j * 16, 75, '#789683', 2.6);
    }
    dashRow(-339, 66, 439, '#789281', 7);
    dashRow(-339, 100, 374, '#879c88', 7);
    if (selection > 0) {
      ctx.save(); ctx.globalAlpha *= selection;
      const underline = ramp(8.7, 10.25);
      line(-339, 119, -339 + 374 * underline, 119, '#4e8c76', 2.8);
      const read = ((sceneT - 10.65) / 3.1) % 1;
      if (sceneT >= 10.65 && read >= 0) {
        ctx.save(); ctx.globalAlpha *= Math.pow(Math.sin(Math.PI * read), 2);
        circle(-336 + 367 * read, 119, 3.2, '#416e60'); ctx.restore();
      }
      ctx.restore();
    }
    // Supporting notes occupy a separate left column, clear of the handle lane.
    box(-406, 211, 206, 6, 3, '#a6b2a2');
    box(-406, 236, 177, 6, 3, '#a6b2a2');
    line(-406, 286, -220, 286, '#c3d0c0', 2);
    text('SOURCE INDEX', -406, 320, 13, '#7c9383', 'left', 189);
  }
  function polyline(points, amount, color, thickness, alpha) {
    if (amount <= 0 || alpha <= 0) return;
    const lengths = [];
    let total = 0;
    for (let i = 1; i < points.length; i++) { const len = Math.hypot(points[i].x - points[i - 1].x, points[i].y - points[i - 1].y); lengths.push(len); total += len; }
    let remaining = total * clamp(amount);
    ctx.save(); ctx.globalAlpha *= alpha;
    ctx.beginPath(); ctx.moveTo(points[0].x, points[0].y);
    for (let i = 0; i < lengths.length; i++) {
      const q = Math.min(1, remaining / lengths[i]);
      ctx.lineTo(mix(points[i].x, points[i + 1].x, q), mix(points[i].y, points[i + 1].y, q));
      remaining -= lengths[i]; if (remaining <= 0) break;
    }
    ctx.strokeStyle = color; ctx.lineWidth = thickness; ctx.stroke(); ctx.restore();
  }
  function pointOnPath(points, amount) {
    const lengths = [];
    let total = 0;
    for (let i = 1; i < points.length; i++) { const len = Math.hypot(points[i].x - points[i - 1].x, points[i].y - points[i - 1].y); lengths.push(len); total += len; }
    let remaining = clamp(amount) * total;
    for (let i = 0; i < lengths.length; i++) {
      if (remaining <= lengths[i]) { const q = remaining / lengths[i]; return { x: mix(points[i].x, points[i + 1].x, q), y: mix(points[i].y, points[i + 1].y, q) }; }
      remaining -= lengths[i];
    }
    return points[points.length - 1];
  }

  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over'; ctx.filter = 'none';
  ctx.shadowBlur = 0; ctx.shadowColor = 'transparent'; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
  ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.setLineDash([]);
  // A restrained static linear backdrop, with no glow or radial lighting.
  const background = ctx.createLinearGradient(0, height, width, 0);
  background.addColorStop(0, '#10232b'); background.addColorStop(0.54, '#182d35');
  background.addColorStop(1, '#253442');
  ctx.fillStyle = background; ctx.fillRect(0, 0, width, height);
  ctx.translate(width / 2 - 36 * scale, height / 2); ctx.scale(scale, scale);

  // A source tab is attached behind the page and never enters the reading columns.
  box(175, -189, 53, 45, 10, '#d6b777', ink, 3.5);
  line(207, -175, 219, -175, '#6b795e', 2);
  line(207, -163, 219, -163, '#6b795e', 2);
  paper(); box(-443, -353, 626, 706, 18, null, '#d3dbcd', 1.5);
  content(); box(-455, -365, 650, 730, 26, null, '#365460', 4.5);

  if (selection > 0) {
    ctx.save(); ctx.globalAlpha *= selection;
    // The selection bracket is in the empty margin, not across text.
    ctx.beginPath(); ctx.moveTo(134, 44); ctx.lineTo(146, 44);
    ctx.lineTo(146, 143); ctx.lineTo(134, 143);
    ctx.strokeStyle = '#729b82'; ctx.lineWidth = 3; ctx.stroke(); ctx.restore();
  }
  const route = [{ x: 146, y: 91 }, { x: 169, y: 91 }, { x: 169, y: -166 }, { x: 280, y: -166 }];
  polyline(route, ramp(9.05, 10.5), '#8eb29b', 2.6, connection);
  if (sceneT >= 10.65 && connection > 0) {
    const run = ((sceneT - 10.65) / 2.8) % 1;
    const pos = pointOnPath(route, run);
    ctx.save(); ctx.globalAlpha *= connection * Math.pow(Math.sin(Math.PI * run), 2);
    circle(pos.x, pos.y, 4, '#bed7b8'); ctx.restore();
  }
  if (sourceOpen > 0) {
    ctx.save(); ctx.globalAlpha *= sourceOpen;
    ctx.translate(17 * (1 - sourceOpen), 0);
    const sourcePaper = ctx.createLinearGradient(280, -244, 528, -44);
    sourcePaper.addColorStop(0, '#e1e9dd'); sourcePaper.addColorStop(1, '#cbdccf');
    box(280, -244, 248, 200, 18, sourcePaper, ink, 4);
    text('SOURCE 01', 303, -205, 16, '#426d65', 'left', 203);
    line(302, -187, 506, -187, '#afc4b4', 2);
    for (let i = 0; i < 3; i++) {
      const reveal = smooth((sceneT - (10.65 + i * 0.55)) / 0.8);
      const widths = [200, 182, 151];
      box(303, -166 + i * 27, widths[i] * reveal, 6, 3, '#7e9d8c');
    }
    box(303, -88, 123, 26, 8, '#b9d2bf');
    text('REFERENCED', 364.5, -70, 10.5, '#477562', 'center', 107);
    const saved = ramp(13.0, 14.0);
    ctx.save(); ctx.globalAlpha *= saved;
    ctx.beginPath(); ctx.moveTo(460, -76); ctx.lineTo(467, -69); ctx.lineTo(480, -83);
    ctx.strokeStyle = '#54846c'; ctx.lineWidth = 3; ctx.stroke(); ctx.restore();
    ctx.restore();
  }

  // The handle is a rigid child of the lens. It is drawn underneath the ring.
  ctx.save(); ctx.translate(lens.x, lens.y); ctx.rotate(Math.PI / 4);
  const handleFill = ctx.createLinearGradient(128, -20, 315, 20);
  handleFill.addColorStop(0, '#6eaba5'); handleFill.addColorStop(1, '#45838b');
  box(123, -19, 192, 38, 17, handleFill, ink, 5);
  box(124, -24, 43, 48, 9, '#d2b47b', ink, 4);
  line(278, -10, 278, 10, '#8bb8aa', 2.5);
  line(291, -10, 291, 10, '#8bb8aa', 2.5);
  ctx.restore();

  // True, uniform magnification: redraw the same source geometry inside the lens.
